<script setup lang="ts">
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import AdminFacilityList from '../components/AdminFacilityList.vue'
import AdminAppFacilityRows from '../components/AdminAppFacilityRows.vue'
import AdminReviewCards from '../components/AdminReviewCards.vue'
import TrafficVideo from '../components/TrafficVideo.vue'
import DeadlineTimer from '../components/DeadlineTimer.vue'
import FaqAccordion from '../components/FaqAccordion.vue'
import BackendLayout from '../components/BackendLayout.vue'
import ServiceFields from '../components/ServiceFields.vue'
import {backendResources,resourceRoutes,valueLabels,type Field,type Action} from '../data/backendResources'
import {backend,asPage,queryString,downloadPdf,type PageData} from '../services/backend'
import {useApp} from '../stores/app'
const props=defineProps<{resourceKey?:string;embedded?:boolean;operationsOnly?:boolean}>()
const emit=defineEmits<{saved:[]}>()
const route=useRoute(),app=useApp(),resourceId=computed(()=>String(props.resourceKey||route.params.resource||resourceRoutes[route.path]||'facilities')),resource=computed(()=>backendResources[resourceId.value]),customer=computed(()=>resource.value?.owner||['/c-notice','/info/faq','/customer-app/notices','/customer-app/faq'].includes(route.path))
const restored=computed(()=>!customer.value&&!route.path.startsWith('/admin-app/'))
const facilityList=computed(()=>restored.value&&resourceId.value==='facilities')
const appFacilityList=computed(()=>route.path==='/admin-app/screen-4'&&resourceId.value==='facilities')
const customerService=computed(()=>restored.value&&['customers','inquiries','notices','faqs'].includes(resourceId.value))
const riskFilter=ref('')
const facilityRows=computed(()=>data.value.items.filter(row=>!riskFilter.value||row.currentRiskLevel===riskFilter.value))
function reviewTab(status:string){filters.reviewStatus=status;search()}
async function review(row:Record<string,any>,number:string){await open('action',row,resource.value.actions?.[0]);values.correctedNum=number}
const publicNotices=computed(()=>customer.value&&resourceId.value==='notices')
const readNotices=ref<Record<string,string>>({})
const noticeReadKey=computed(()=>`routel-read-notices:${app.account?.role||'guest'}:${app.account?.id||'guest'}`)
watch(noticeReadKey,key=>{try{const stored=JSON.parse(localStorage.getItem(key)||'{}');readNotices.value=stored&&typeof stored==='object'&&!Array.isArray(stored)?stored:{}}catch{readNotices.value={}}},{immediate:true})
function noticeVersion(row:Record<string,any>){return String(row.updatedAt||row.createdAt||'read')}
function noticeUnread(row:Record<string,any>){return publicNotices.value&&readNotices.value[String(row.id)]!==noticeVersion(row)}
function markNoticeRead(row:Record<string,any>){readNotices.value={...readNotices.value,[String(row.id)]:noticeVersion(row)};try{localStorage.setItem(noticeReadKey.value,JSON.stringify(readNotices.value))}catch{/* Reading still works when browser storage is unavailable. */}}
async function loadCollection(signal:AbortSignal){
 const fetchPage=async(current:number)=>asPage<Record<string,any>>(await backend(path(resource.value.path)+queryString({...filters,page:current,size:100}),{signal}),current,100)
 const first=await fetchPage(1),items=[...first.items]
 for(let current=2;current<=first.totalPages;current++)items.push(...(await fetchPage(current)).items)
 if(resourceId.value==='notices')items.sort((a,b)=>Number(Boolean(b.important))-Number(Boolean(a.important)))
 if((facilityList.value||appFacilityList.value)&&riskFilter.value){const selected=items.filter(row=>row.currentRiskLevel===riskFilter.value);items.splice(0,items.length,...selected)}
 const totalPages=Math.ceil(items.length/20)
 page.value=Math.min(page.value,Math.max(1,totalPages))
 return {items:items.slice((page.value-1)*20,page.value*20),page:page.value,size:20,totalItems:items.length,totalPages}
}
const visibleColumns=computed(()=>publicNotices.value?resource.value.columns.filter(([key])=>key!=='important'):resource.value.columns)
const pageTitle=computed(()=>customer.value&&resourceId.value==='notices'?'공지사항':customer.value&&resourceId.value==='faqs'?'자주 묻는 질문 (FAQ)':resource.value.title)
function displayField(key:string,value:any){return resourceId.value==='notices'&&key==='important'?(value?'중요 공지':'일반 공지'):display(value)}
const relatedIds=computed(()=>{const groups=[['facilities','cameras','thresholds','transits','events','reviews','transfers','risk-history'],['managers','regions','shifts'],['display','presets','reasons'],['customers','inquiries','notices','faqs','alerts']];return groups.find(group=>group.includes(resourceId.value))||[]})
const canWrite=computed(()=>resource.value?.owner?app.account?.role==='customer':!customer.value&&app.account?.role==='REGIONAL_ADMIN')
const filters=reactive<Record<string,any>>({}),parents=reactive<Record<string,any>>({}),choices=reactive<Record<string,{value:string;label:string}[]>>({}),values=reactive<Record<string,any>>({})
const acknowledge=ref(false)
const data=ref<PageData<Record<string,any>>>({items:[],page:1,size:20,totalItems:0,totalPages:0}),page=ref(1),loading=ref(false),error=ref(''),message=ref(''),saving=ref(false),modal=ref<HTMLDialogElement>(),selected=ref<Record<string,any>|null>(null),mode=ref(''),formFields=ref<Field[]>([]),action=ref<Action>(),detail=ref<Record<string,any>>({})
let abort:AbortController|undefined,request=0,alive=true
function path(template:string,row=selected.value){return template.replace(/\{(\w+)\}/g,(_,key)=>encodeURIComponent(String(key==='id'?row?.[resource.value.rowKey||'id']:parents[key]??row?.[key]??'')))}
const missingParent=computed(()=>resource.value?.parents?.some(field=>field.required&&!parents[field.key]))
async function lookup(fields:Field[],row?:Record<string,any>){const scope=resourceId.value;for(const field of fields){if(!field.source)continue;let url=field.source==='underpasses'?'/api/underpasses?size=500':field.source==='regions'?'/api/regions':field.source==='shifts'?'/api/shifts':field.source==='presets'?'/api/display/presets':field.source==='reasons'?'/api/control/reason-presets':`/api/underpasses/${row?.id||parents.underpassId}/cameras`;if(field.source==='cameras'&&!row?.id&&!parents.underpassId)continue;try{const result=await backend(url);if(alive&&scope===resourceId.value&&(!row||selected.value?.id===row.id))choices[field.key]=asPage<any>(result).items.map(item=>({value:String(item.id),label:item.name||item.content||`${item.cameraRole} · ${item.id}`}))}catch{/* Main list retains its own request error. */}}}
async function load(){if(props.operationsOnly)return;if(!resource.value||missingParent.value)return;abort?.abort();abort=new AbortController();const seq=++request;loading.value=true;error.value='';try{if(filters.startDate&&filters.endDate&&filters.startDate>filters.endDate)throw new Error('시작일은 종료일보다 늦을 수 없습니다.');const result=(resourceId.value==='notices'||facilityList.value||appFacilityList.value)?await loadCollection(abort.signal):await backend(path(resource.value.path)+queryString({...filters,page:page.value,size:20}),{signal:abort.signal});if(seq===request)data.value=asPage(result,page.value)}catch(e){if(seq===request&&!abort.signal.aborted)error.value=(e as Error).message}finally{if(seq===request)loading.value=false}}
function imageUrl(value:string){if(!value)return '';const parts=value.replace(/^\/api\/uploads\//,'').split(/[\\/]/);if(parts.some(part=>part==='..'||part==='.')||value.includes(':'))return '';return '/api/uploads/'+parts.filter(Boolean).map(encodeURIComponent).join('/')}
function display(value:any){if(value==null||value==='')return '—';if(typeof value==='boolean')return value?'예':'아니요';if(Array.isArray(value))return value.map(item=>typeof item==='object'?item.name||item.id:item).join(', ');if(typeof value==='object')return value.name||'—';return valueLabels[String(value)]||String(value).replace('T',' ')}
function openDialog(){if(modal.value&&!modal.value.open)modal.value.showModal()}
async function open(kind:string,row?:Record<string,any>,itemAction?:Action){acknowledge.value=false;selected.value=row||null;mode.value=kind;action.value=itemAction;error.value='';message.value='';Object.keys(values).forEach(key=>delete values[key]);detail.value=row||{};formFields.value=kind==='remove'||kind==='detail'||kind==='video'?[]:kind==='action'?itemAction?.fields||[]:resource.value.fields||[];try{if(row&&resource.value.detail){detail.value=await backend(`${path(resource.value.path)}/${encodeURIComponent(row.id)}`)}for(const field of formFields.value){const value=field.key==='eventId'?detail.value.currentBlockEventId:field.key==='content'&&resourceId.value==='inquiries'&&kind==='action'?(itemAction?.method==='POST'?'':detail.value.replyContent):field.key==='correctedNum'?(detail.value.correctedNum||detail.value.detectedNum):detail.value[field.key];values[field.key]=field.type==='multi'?(Array.isArray(value)?value.map(v=>String(v.id||v)):[]):field.type==='checkbox'?Boolean(value):Array.isArray(value)?value.join('\n'):value==null?'':String(value)}void lookup(formFields.value,row);openDialog();if(publicNotices.value&&kind==='detail'&&row)markNoticeRead(row)}catch(e){error.value=(e as Error).message}}
function body(){const result:Record<string,unknown>={};for(const field of formFields.value){const value=values[field.key];if(field.type==='multi')result[field.key]=(value||[]).map(Number);else if(field.type==='lines')result[field.key]=String(value||'').split(/\n/).map(v=>v.trim()).filter(Boolean);else if(field.type==='checkbox')result[field.key]=Boolean(value);else if(field.type==='number'||field.source)result[field.key]=value===''?null:Number(value);else result[field.key]=value===''?null:value}return result}
async function submit(){if(saving.value)return;saving.value=true;error.value='';try{if(resourceId.value==='display'&&mode.value!=='remove'&&!values.presetId&&!String(values.content||'').trim())throw new Error('문구를 선택하거나 입력해 주세요.');if(resourceId.value==='customers'&&mode.value==='edit'&&!acknowledge.value)throw new Error('주소·비상 연락처 교체 내용을 확인해 주세요.');let url=path(resource.value.path),method='POST',pdf=false,payload:unknown=body();if(mode.value==='edit'){url+=`/${encodeURIComponent(selected.value?.[resource.value.rowKey||'id'])}`;method='PUT'}if(mode.value==='remove'){url+=`/${encodeURIComponent(selected.value?.[resource.value.rowKey||'id'])}`;method='DELETE';payload=undefined}if(mode.value==='action'&&action.value){url=path(action.value.path);method=action.value.method||'POST';pdf=!!action.value.pdf;if(!formFields.value.length)payload=undefined}const result=await backend(url,{method,body:payload,pdf});if(pdf)downloadPdf(result,`이관문서-${selected.value?.id||'시설'}.pdf`);if(resourceId.value==='my-inquiries'&&mode.value==='create')sessionStorage.removeItem('routel-inquiry-draft');modal.value?.close();message.value='요청이 처리되었습니다.';await load();emit('saved')}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
function search(){page.value=1;void load()}
function navigatePage(next:number){page.value=next;void load()}
const labels=computed(()=>Object.fromEntries([...resource.value.columns,...(resource.value.fields||[]).map(field=>[field.key,field.label]),['content','내용'],['answer','답변'],['replyContent','답변 내용'],['replyAuthorName','답변자'],['repliedAt','답변일'],['roadAddress','주소']]))
watch(()=>route.fullPath,()=>{abort?.abort();request++;modal.value?.close();for(const obj of [filters,parents,choices])Object.keys(obj).forEach(key=>delete obj[key]);page.value=1;data.value={items:[],page:1,size:20,totalItems:0,totalPages:0};error.value='';if(!resource.value){error.value='페이지를 찾을 수 없습니다.';return}for(const field of resource.value.parents||[])parents[field.key]=route.query[field.key]||'';for(const field of resource.value.filters||[])if(route.query[field.key])filters[field.key]=route.query[field.key];if(props.operationsOnly)return;if(resourceId.value==='reviews'&&!filters.reviewStatus)filters.reviewStatus='PENDING';void lookup([...(resource.value.parents||[]),...(resource.value.filters||[])]);void load().then(()=>{if(!props.embedded&&route.query.id&&resource.value.detail&&resourceId.value!=='faqs')void open('detail',{id:Number(route.query.id)});else if(route.path==='/my-inquiry-new')void open('create').then(()=>{try{const draft=JSON.parse(sessionStorage.getItem('routel-inquiry-draft')||'null');if(draft){values.title=draft.title||'';values.content=draft.content||''}}catch{}})})},{immediate:true})
onBeforeUnmount(()=>{alive=false;abort?.abort();modal.value?.close()})
defineExpose({open,load})
</script>
<template><component :is="customer||props.embedded?'div':BackendLayout"><section v-if="resource" class="service-workspace" :class="{'restored-admin-workspace':restored,'resource-operations-only':props.operationsOnly}"><div v-if="restored" class="crumb">{{customerService?'고객 서비스':pageTitle}}</div><div class="service-heading page-head"><component :is="props.embedded?'h2':'h1'">{{pageTitle}}</component><div class="service-actions"><button type="button" :disabled="loading||missingParent" @click="load">새로고침</button><button v-if="resource.create&&canWrite" type="button" @click="open('create')">{{resourceId==='cars'?'차량 등록':facilityList?'+ 지하차도 등록':'새로 등록'}}</button></div></div><nav v-if="customerService" class="tabs" aria-label="고객 서비스 탭"><RouterLink to="/cs-customers">고객 조회</RouterLink><RouterLink to="/cs-inquiries">문의 처리</RouterLink><RouterLink to="/cs-content">공지사항</RouterLink><RouterLink to="/admin-data/faqs">FAQ</RouterLink></nav><nav v-else-if="restored&&resourceId==='reviews'" class="tabs review-tabs" aria-label="판별 구분"><button type="button" :aria-pressed="filters.reviewStatus==='PENDING'" @click="reviewTab('PENDING')">대기</button><button type="button" :aria-pressed="filters.reviewStatus!=='PENDING'" @click="reviewTab('')">처리 이력</button></nav><nav v-else-if="!customer&&!facilityList&&!appFacilityList&&!route.path.startsWith('/admin-app/')" class="service-tabs tabs" aria-label="관리 기능"><RouterLink v-for="id in relatedIds" :key="id" :to="'/admin-data/'+id">{{backendResources[id]?.title}}</RouterLink></nav><form v-if="facilityList||appFacilityList" class="filters restored-facility-filters" role="search" @submit.prevent="search"><div class="chips" role="group" aria-label="위험 단계"><button v-for="[value,label] in [['','전체'],['DANGER','위험'],['WARNING','주의'],['SAFE','안전']]" :key="value" class="chip" type="button" :aria-pressed="riskFilter===value" @click="riskFilter=value;search()">{{label}}</button></div><select v-model="filters.regionId" aria-label="담당 지역" @change="search"><option value="">담당 지역 전체</option><option v-for="option in choices.regionId" :key="option.value" :value="option.value">{{option.label}}</option></select><select v-model="filters.status" aria-label="통제 상태" @change="search"><option value="">통제 상태 전체</option><option value="BLOCKED">통제 중</option><option value="NORMAL">정상 운영</option></select><input v-model="filters.keyword" type="search" placeholder="지하차도 이름 검색" aria-label="지하차도 이름 검색"><button class="btn sm" type="submit">조회</button><span class="sub">총 {{data.totalItems}}곳</span></form><form v-else class="service-filters filters" @submit.prevent="search"><ServiceFields v-if="resource.parents?.length" :fields="resource.parents" :values="parents" :choices="choices"/><ServiceFields v-if="resource.filters?.length" :fields="resource.filters" :values="filters" :choices="choices"/><button type="submit" :disabled="loading">조회</button></form><p v-if="error" class="service-error" role="alert">{{error}} <RouterLink v-if="!app.account" :to="customer?'/login':'/admin-login'">로그인</RouterLink></p><p v-if="message" class="service-message" role="status">{{message}}</p><p v-if="missingParent">위에서 {{resource.parents?.map(field=>field.label).join(' · ')}}를 선택하고 조회하세요.</p><p v-else-if="loading" role="status">불러오는 중입니다.</p><template v-else><AdminAppFacilityRows v-if="appFacilityList" :items="facilityRows"/><AdminFacilityList v-else-if="facilityList" :items="facilityRows" :total="data.totalItems" @detail="row=>open('detail',row)" @control="row=>open('action',row,resource.actions?.[row.currentStatus==='BLOCKED'?1:0])"/><AdminReviewCards v-else-if="restored&&resourceId==='reviews'&&filters.reviewStatus==='PENDING'" :items="data.items.filter(row=>row.reviewStatus==='PENDING')" :saving="saving" @review="review"/><FaqAccordion v-else-if="resourceId==='faqs'" :items="data.items" :manage="canWrite" :initial-open-id="String(route.query.id||'')" @edit="row=>open('edit',row)" @remove="row=>open('remove',row)"/><div v-else class="service-table-wrap"><table class="service-table"><thead><tr><th v-for="[key,label] in visibleColumns" :key="key">{{label}}</th><th v-if="!publicNotices">상세·처리</th></tr></thead><tbody><tr v-for="(row,index) in data.items" :key="row.id||index"><td v-for="[key,label] in visibleColumns" :key="key" :data-label="label"><template v-if="resourceId==='notices'&&key==='title'"><button type="button" class="notice-title-button" :class="{'notice-unread':noticeUnread(row)}" @click="open('detail',row)"><span v-if="row.important" class="notice-important-badge">중요</span><span>{{row.title}}</span></button></template><template v-else-if="resourceId==='notices'&&key==='important'"><span :class="row.important?'notice-important-badge':'notice-regular-label'">{{row.important?'중요':'일반'}}</span></template><img v-else-if="key==='imagePath'&amp;&amp;imageUrl(row[key])&amp;&amp;!row.imageUnavailable" :src="imageUrl(row[key])" alt="번호판 인식 이미지" loading="lazy" @error="row.imageUnavailable=true"><template v-else-if="key==='reviewDeadline'&&row.reviewStatus==='PENDING'&&row[key]"><DeadlineTimer :deadline="row[key]"/><br><small>{{display(row[key])}}</small></template><template v-else-if="restored&&resourceId==='customers'&&key==='name'"><button type="button" class="notice-title-button" @click="open('detail',row)">{{row.name}}</button></template><template v-else>{{key==='imagePath'?'이미지 없음':display(row[key])}}</template></td><td v-if="!publicNotices"><div class="service-actions"><button v-if="resourceId==='cameras'&amp;&amp;row.streamUrl" @click="open('video',row)">영상 보기</button><button v-if="resource.detail" @click="open('detail',row)">상세 보기</button><button v-if="resource.edit&&canWrite" @click="open('edit',row)">수정</button><button v-if="resource.remove&&canWrite" @click="open('remove',row)">삭제</button><button v-for="act in canWrite?resource.actions||[]:[]" :key="act.label" @click="open('action',row,act)">{{act.label}}</button><RouterLink v-if="resourceId==='facilities'" :to="'/admin-data/cameras?underpassId='+row.id">카메라·입출구</RouterLink></div></td></tr><tr v-if="!data.items.length"><td :colspan="visibleColumns.length+(publicNotices?0:1)">조회된 항목이 없습니다.</td></tr></tbody></table></div><div class="service-pagination"><button :disabled="page<=1" @click="navigatePage(page-1)">이전</button><span>{{page}} / {{Math.max(1,data.totalPages)}} · {{data.totalItems}}건</span><button :disabled="page>=data.totalPages" @click="navigatePage(page+1)">다음</button></div></template><dialog ref="modal" class="service-modal" :class="{'restored-summary-drawer':restored&&mode==='detail'&&['facilities','customers'].includes(resourceId)}" @close="mode=''"><form @submit.prevent="submit"><header><h2>{{mode==='video'?'카메라 영상':mode==='detail'?(restored&&detail.name?detail.name:'상세 보기'):mode==='create'?'새로 등록':mode==='edit'?'정보 수정':mode==='remove'?'삭제 확인':action?.label}}</h2><button type="button" :disabled="saving" @click="modal?.close()">닫기</button></header><TrafficVideo v-if="mode==='video'" :src="selected?.streamUrl" :hls="true"/><img v-if="resourceId==='reviews'&amp;&amp;imageUrl(selected?.imagePath)" :src="imageUrl(selected?.imagePath)" alt="확인할 번호판" style="max-width:100%;max-height:300px;object-fit:contain"><div v-if="restored&&mode==='detail'&&resourceId==='facilities'" class="restored-summary-overview"><span class="badge" :class="detail.currentRiskLevel==='DANGER'?'danger':detail.currentRiskLevel==='WARNING'?'warn':'safe'">{{display(detail.currentRiskLevel)}}</span><strong>{{detail.riskScore??'—'}}점</strong><span>{{detail.currentStatus==='BLOCKED'?'통제 중':'정상 운영'}}</span><div class="restored-risk-gauge"><b :style="{width:Math.max(0,Math.min(100,Number(detail.riskScore)||0))+'%'}"></b></div></div><dl v-if="mode==='detail'" class="service-detail"><template v-for="(label,key) in labels" :key="key"><template v-if="detail[key]!=null"><dt>{{label}}</dt><dd>{{displayField(String(key),detail[key])}}</dd></template></template></dl><div v-if="mode==='detail'&&canWrite" class="service-actions"><button v-if="resource.edit" type="button" @click="open('edit',detail)">수정</button><button v-if="resource.remove" type="button" @click="open('remove',detail)">삭제</button><RouterLink v-if="facilityList" :to="'/admin-data/cameras?underpassId='+detail.id">카메라·입출구</RouterLink><button v-for="act in resource.actions||[]" :key="act.label" type="button" @click="open('action',detail,act)">{{act.label}}</button></div><template v-if="mode!=='detail'&amp;&amp;mode!=='video'"><p v-if="mode==='remove'">선택한 항목을 삭제하시겠습니까?</p><p v-else-if="mode==='action'&&!formFields.length">선택한 항목에 대해 {{action?.label}} 작업을 진행하시겠습니까?</p><div v-if="resourceId==='customers'&amp;&amp;mode==='edit'" class="service-message"><p>목록에는 기존 주소·비상 연락처가 제공되지 않습니다. 저장하면 해당 항목도 입력한 값으로 교체됩니다.</p><label><input v-model="acknowledge" type="checkbox" required> 주소·비상 연락처 교체를 확인했습니다.</label></div><ServiceFields :fields="formFields" :values="values" :choices="choices" :disabled="saving"/></template><p v-if="error" class="service-error" role="alert">{{error}}</p><footer v-if="mode!=='detail'&amp;&amp;mode!=='video'"><button type="button" :disabled="saving" @click="modal?.close()">취소</button><button type="submit" :disabled="saving">{{saving?'처리 중…':'확인'}}</button></footer></form></dialog></section><p v-else role="alert">페이지를 찾을 수 없습니다.</p></component></template>

<style scoped>
.resource-operations-only>:not(dialog){display:none!important}

.service-workspace .notice-title-button{display:inline-flex;align-items:center;gap:10px;min-height:32px;padding:0;border:0;border-radius:0;background:transparent;color:inherit;text-align:left;font:inherit;line-height:1.6;max-width:100%}
.notice-title-button>span:last-child{overflow-wrap:anywhere;min-width:0}
.notice-title-button:hover>span:last-child{text-decoration:underline;text-underline-offset:3px}
.notice-important-badge{display:inline-block;flex-shrink:0;padding:3px 9px;border-radius:5px;background:#fff0ed;color:#b42318;font-size:11px;font-weight:700;line-height:18px;white-space:nowrap}
.notice-regular-label{color:var(--ink-sub,#64748b);font-size:12px}
